import pytest

from lab1.money import Money, format_money


def test_add_same_currency(ten_shekels):
    assert ten_shekels.add(Money(250)).amount == 1250


def test_add_other_currency_fails(ten_shekels):
    with pytest.raises(ValueError):
        ten_shekels.add(Money(100, "USD"))


@pytest.mark.parametrize(
    ("amount", "expected"),
    [(1000, "10.00 ILS"), (5, "0.05 ILS"), (123456, "1234.56 ILS")],
)
def test_format_money(amount, expected):
    assert format_money(Money(amount)) == expected

